def main(argv=None):
    argv = sys.argv[1:] if argv is None else argv
    if argv == ["check"]:
        config = load_config()
        missing = [k for k, (v, _) in config.items() if v is None]
        print("missing: " + ", ".join(missing) if missing else "ok")
        return 1 if missing else 0
    if argv == ["doctor"]:
        # Output is meant to be pasted into support tickets: never print secrets.
        for key, (value, source) in load_config().items():
            if value is None:
                shown = "(not set)"
            elif is_secret(key):
                shown = "<redacted, %d chars>" % len(value)
            else:
                shown = value
            print("%s = %s [%s]" % (key, shown, source))
        return 0
    print("usage: python -m payhook check|doctor", file=sys.stderr)
    return 2


sys.exit(main())

